import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("sheet notes", () => {
  test("sheet notes", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    expect(await ui.addNote(pg_uma, "first")).toBe(true);
    expect(await ui.addNote(pg_uma, " ")).toBe(false);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    await ui.setToday(pg_vic, "2026-03-11");
    expect(await ui.addNote(pg_vic, "second")).toBe(true);
    expect(await ui.delegate(pg_vic, {"user": "uma", "from": "2026-03-11", "to": "2026-03-12"})).toBe(true);
    await ui.refresh(pg_uma);
    expect(await ui.addNote(pg_uma, "third")).toBe(true);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.addNote(pg_wes, "nope")).toBe(false);
    await ui.refresh(pg_vic);
    expect(await ui.archive(pg_vic)).toBe(true);
    expect(await ui.addNote(pg_vic, "late")).toBe(false);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("note-line")).toHaveText(["2026-03-11 uma: third", "2026-03-11 vic: second", "2026-03-10 uma: first"]);
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `ROLE_SET sheet=${sheet} by=uma user=wes role=viewer`,
      `ROLE_SET sheet=${sheet} by=uma user=vic role=steward`,
      `NOTE_ADDED sheet=${sheet} by=uma text=first`,
      `SNAPSHOT sheet=${sheet} by=vic name=Ada due-total=0.00`,
      `NOTE_ADDED sheet=${sheet} by=vic text=second`,
      `DELEGATED sheet=${sheet} by=vic user=uma from=2026-03-11 to=2026-03-12`,
      `NOTE_ADDED sheet=${sheet} by=uma text=third for=vic`,
      `SHEET_ARCHIVED sheet=${sheet} by=vic`
    ]);
  });
  test("sheet notes scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "terms", "30");
    await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    await ui.setSetting(pg_uma, "proof-threshold", "1.00");
    expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
    await ui.setSetting(pg_uma, "grace-days", "3");
    expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
    expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
    await ui.setSetting(pg_uma, "grace-B", "5");
    expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "7.77", "note": "tpl"})).toBe(true);
    await ui.setSetting(pg_uma, "pot", "33.33");
    await ui.setSetting(pg_uma, "review-threshold", "4.00");
    await ui.setSetting(pg_uma, "review-sla", "5");
    await ui.setSetting(pg_uma, "proof-kinds", "receipt");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "terms": "20", "contact": "ADA@X", "tags": "a"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": " Ada@x ", "tags": "c"})).toBeNull();
    expect(await ui.addPool(pg_uma, "P1")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "33.33", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "33.33"})).toBe(true);
    expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "0.04", "date": "2026-03-20"}));
    expect(await ui.claimEditOpen(pg_uma, c_ada_0)).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimEditOpen(pg_vic, c_ada_0)).toBe(false);
    await ui.refresh(pg_uma);
    expect(await ui.claimEditSave(pg_uma, c_ada_0, {"amount": "7.77"})).toBe(true);
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "12.50", "date": "2026-03-15", "tags": "b,a,a"}));
    expect(await ui.claimAction(pg_uma, c_ada_1, "void", "dup")).toBe(true);

