            boolean about = number != null
                    ? number.equals(numbered)
                    : numbered == null && fields.contains("person=" + person) && fields.contains("amount=" + amount)
                            && fields.contains("date=" + date);
            if (about) found.add(line);
        }
        return found;
    }

    private static boolean isAbout(String[] parts, String who) {
        for (int i = 2; i < parts.length; i++) {
            String p = parts[i];
            String value = p.startsWith("name=") ? p.substring(5) : p.startsWith("person=") ? p.substring(7) : null;
            if (value != null && value.trim().toLowerCase(Locale.ROOT).equals(who)) {
                return true;
            }
        }
        return false;
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
