import { createContext, useContext } from 'react';
import { getJson, getJsonNow } from './http';

/** Set to true around components that must show the sheet as the store holds it now while the screen shows it as
 *  of a date: the shared read hooks then answer as of now, under keys of their own. */
export const ReadNow = createContext(false);

/** How a shared read hook reads: its getter, and its query key (suffixed when it reads now under an as-of date). */
export function useReader(): { get: <T>(path: string) => Promise<T>; key: (key: unknown[]) => unknown[] } {
  const now = useContext(ReadNow);
  return now
    ? { get: getJsonNow, key: (key) => [...key, 'read-now'] }
    : { get: getJson, key: (key) => key };
}
package net.officefloor.hq.app.crew;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.history.AsOfView;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadCrews {
    public void load(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            CrewRepository repository, AsOfView view, Out<Crews> crews) throws BadRequestException {
        CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        crews.set(view.read(connection, id, () -> new Crews(repository.list(id))));
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A member of a crew: a person, by id, and their name now. */
export type CrewMember = { personId: number; name: string };

/** A crew: its name, its lead (by id, and their name now) and its members in the order they were added. */
export type Crew = { name: string; leadId: number; lead: string; members: CrewMember[] };

export function crewsKey(sheetId: string) {
  return ['sheet', sheetId, 'crews'];
}

/** The sheet's crews, by name. */
export function useCrews(sheetId: string) {
  return useQuery({
    queryKey: crewsKey(sheetId),
    queryFn: async () => (await getJson<{ crews: Crew[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/crews`)).crews,
  });
}
